This complete standalone JavaScript example uses a verified-session fixture, not an actual sign-in system:
```javascript
function update(session, entry, minutes) {
  if (!session) return { status: 401 };
  if (session.userId !== entry.ownerId) return { status: 403 };
  if (!Number.isInteger(minutes) || minutes < 1 || minutes > 180) {
    return { status: 400 };
  }
